/** Native regression for the Vista fidelity pass, with real drag/drop bytes and measured graphs. */
public final class FidelitySmoke extends Instrumentation {
    private MainActivity home;private View root;private DesktopStore store;private final Map<String,Object> original=new HashMap<>();private File folder;
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){Bundle result=new Bundle();boolean success=false;try{
        store=new DesktopStore(getTargetContext());original.putAll(store.prefs.getAll());store.prefs.edit().putInt("startup_mode",2).putBoolean("welcome_on_start",false).putBoolean("reduce_motion",true).putBoolean("sidebar_always_top",false).putBoolean("tray_expanded",false).putString("taskbar_grouping","Always").putString("explorer_view_mode","Details").putBoolean("explorer_details",true).putBoolean("desktop_sounds",false).commit();getTargetContext().getSharedPreferences(StorageAccess.PREFS,0).edit().putBoolean("seen",true).commit();getTargetContext().getSharedPreferences(StartupExperience.SESSION,0).edit().putBoolean("seen",true).putBoolean("welcome_seen",true).commit();
        home=(MainActivity)startActivitySync(new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(getTargetContext(),MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));root=home.getWindow().getDecorView();await(()->home.hasWindowFocus(),"Focused desktop");tray();backgrounds();graphs();folders();
        result.putString("stream","PASS: task buttons preserve 0/50/100 glass opacity; equal Quick Launch separators; inline tray arrow and real device icons; draft-only background thumbnails, custom picture decode, Save changes and position; real PID/CPU/RAM/network graph sampling and pause/reduced motion; separate Explorer windows, taskbar family grouping, physical icon drag copy/move with exact bytes and original preservation; real folder desktop links and validated backups.\n");success=true;
    }catch(Throwable error){try{shot("fidelity-failure.png");StringBuilder tree=new StringBuilder();dump(getUiAutomation().getRootInActiveWindow(),tree,0);try(FileOutputStream out=getTargetContext().openFileOutput("fidelity-tree.txt",0)){out.write(tree.toString().getBytes(StandardCharsets.UTF_8));}}catch(Exception ignored){}StringWriter text=new StringWriter();error.printStackTrace(new PrintWriter(text));result.putString("stream","FAIL: "+text);
    }finally{try{shell("settings put global animator_duration_scale 0");if(home!=null)ui(()->home.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT));if(folder!=null)delete(folder);if(store!=null){SharedPreferences.Editor edit=store.prefs.edit().clear();for(Map.Entry<String,Object> item:original.entrySet()){Object value=item.getValue();String key=item.getKey();if(value instanceof String)edit.putString(key,(String)value);else if(value instanceof Boolean)edit.putBoolean(key,(Boolean)value);else if(value instanceof Integer)edit.putInt(key,(Integer)value);else if(value instanceof Long)edit.putLong(key,(Long)value);else if(value instanceof Float)edit.putFloat(key,(Float)value);}edit.commit();}}catch(Exception ignored){}}
        finish(success?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);
    }
    private void tray()throws Exception{
        progress("task opacity, matching separators and inline tray expansion");ui(()->home.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE));await(()->root.getWidth()>root.getHeight(),"Wide tray ready");AeroWallpaper wallpaper=(AeroWallpaper)find(v->v instanceof AeroWallpaper);for(int opacity:new int[]{0,50,100}){store.prefs.edit().putBoolean("aero_transparency",true).putInt("aero_opacity",opacity).commit();for(boolean active:new boolean[]{false,true}){Bitmap bitmap=Bitmap.createBitmap(80,48,Bitmap.Config.ARGB_8888);AeroGlass surface=new AeroGlass(wallpaper,AeroGlass.TASKBUTTON);surface.active(active);surface.setBounds(0,0,80,48);ui(()->surface.draw(new Canvas(bitmap)));check(Math.abs(Color.alpha(bitmap.getPixel(40,24))-Math.round(opacity*255/100f))<=1,"Task button honors opacity for active="+active);if(opacity==0)for(int y=0;y<48;y++)for(int x=0;x<80;x++)check(bitmap.getPixel(x,y)==0,"No opaque task edges");bitmap.recycle();}}
        store.prefs.edit().putInt("aero_opacity",85).commit();View a=find(v->"Quick Launch separator".equals(v.getContentDescription())),b=find(v->"Taskbar commands".equals(v.getContentDescription()));check(a instanceof TaskbarSeparator&&b instanceof TaskbarSeparator&&a.getWidth()==b.getWidth(),"Identical separator drawing and width");tap(find(v->"Device controls".equals(v.getContentDescription())),60);await(()->find(v->v.getContentDescription()!=null&&v.getContentDescription().toString().startsWith("Battery status"))!=null,"Arrow reveals inline battery");check(store.prefs.getBoolean("tray_expanded",false),"Expansion persists");shot("vista-tray-expanded.png");tap(find(v->"Device controls".equals(v.getContentDescription())),60);await(()->!store.prefs.getBoolean("tray_expanded",true),"Arrow collapses");check(find(v->"Brightness control".equals(v.getContentDescription()))!=null,"Brightness remains directly accessible");ui(()->home.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT));await(()->root.getWidth()<root.getHeight(),"Portrait restored");
    }
    private void backgrounds()throws Exception{
        progress("background preview, save, custom picture and position");int saved=store.prefs.getInt("wallpaper",0);ui(()->home.open("setting:page:background"));VistaControlPanel control=(VistaControlPanel)window("@control").body;int choice=saved==1?2:1;tap(find(control,v->("Preview background: "+(choice==1?"Twilight":"Meadow")).equals(v.getContentDescription())),60);check(store.prefs.getInt("wallpaper",0)==saved,"Thumbnail only previews");tap(text(control,"Save changes"),60);check(store.prefs.getInt("wallpaper",0)==choice,"Save applies");shot("vista-background-picker.png");
        folder=new File(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOCUMENTS),"Nth-Fidelity-"+SystemClock.uptimeMillis());check(folder.mkdirs(),"Isolated fixture directory");File picture=new File(folder,"Background.png");Bitmap image=Bitmap.createBitmap(160,80,Bitmap.Config.ARGB_8888);image.eraseColor(0xffc64e46);try(FileOutputStream out=new FileOutputStream(picture)){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();String uri=StorageAccess.document("Documents/"+folder.getName()+"/Background.png").toString();ui(()->control.wallpaperChosen(uri));await(()->{View save=text(control,"Save changes");return save!=null&&save.isEnabled();},"Actual selected image decodes");Spinner positions=(Spinner)find(control,v->"Picture position".equals(v.getContentDescription()));ui(()->positions.setSelection(1));tap(text(control,"Save changes"),60);check(uri.equals(store.prefs.getString("wallpaper_photo",""))&&store.prefs.getString("wallpaper_position","").equals("Fit"),"Selected content URI and position applied");close("@control");
    }
    private void graphs()throws Exception{
        progress("real monitor metrics, animated interpolation, reduced motion and pause");ui(()->home.open("@taskmanager"));TaskManagerPanel panel=(TaskManagerPanel)window("@taskmanager").body;tap(find(panel,v->"Task Manager Performance".equals(v.getContentDescription())),60);int count=panel.sampleCount();await(()->panel.sampleCount()>count,"Actual CPU/memory sampling advances");check(panel.animatedGraphCount()==0,"Reduced motion leaves graph static");shell("settings put global animator_duration_scale 1");store.prefs.edit().putBoolean("reduce_motion",false).commit();await(()->panel.animatedGraphCount()>0,"Real samples animate with motion enabled");shot("vista-taskmanager-graphs.png");tap(text(panel,"View"),60);menuTap("Pause updates");int paused=panel.sampleCount();Thread.sleep(2300);check(paused==panel.sampleCount()&&panel.animatedGraphCount()==0,"Paused counters and animations stop");tap(find(panel,v->"Task Manager Processes".equals(v.getContentDescription())),60);check(find(panel,v->v instanceof TextView&&((TextView)v).getText().toString().contains("PID "+android.os.Process.myPid()))!=null,"Real process PID is shown");tap(find(panel,v->"Task Manager Networking".equals(v.getContentDescription())),60);check(find(panel,v->"Device received traffic history".equals(v.getContentDescription()))!=null,"Native network graph exists");close("@taskmanager");store.prefs.edit().putBoolean("reduce_motion",true).commit();shell("settings put global animator_duration_scale 0");
    }
    private void folders()throws Exception{
        progress("separate folder windows and physical cross-window copy/move");File destination=new File(folder,"Destination");check(destination.mkdir(),"Destination exists");byte[] bytes="Drag preserves real bytes — café".getBytes(StandardCharsets.UTF_8);File source=new File(folder,"Source.txt");try(FileOutputStream out=new FileOutputStream(source)){out.write(bytes);}String page=DocumentFolders.rootPage(StorageAccess.tree().toString(),"Internal storage");page=DocumentFolders.childPage(page,DocumentOps.stat(home,StorageAccess.document("Documents"),new DocumentOps.Cancel()));page=DocumentFolders.childPage(page,DocumentOps.stat(home,StorageAccess.document("Documents/"+folder.getName()),new DocumentOps.Cancel()));String sourcePage=page;ui(()->home.open("@files"));VistaExplorer explorer=(VistaExplorer)window("@files").body;ui(()->explorer.navigate(sourcePage));await(()->find(explorer,v->"Destination".equals(v.getContentDescription()))!=null,"Real folder listing");tap(find(explorer,v->"Destination".equals(v.getContentDescription())),700);menuTap("Open in new window");await(()->find(v->v instanceof DesktopWindow&&((DesktopWindow)v).toolId.startsWith("@explorer:"))!=null,"Creates separate Explorer");DesktopWindow second=(DesktopWindow)find(v->v instanceof DesktopWindow&&((DesktopWindow)v).toolId.startsWith("@explorer:"));VistaExplorer target=(VistaExplorer)second.body;await(()->find(target,v->"Empty folder".equals(v.getContentDescription()))!=null,"Independent destination path");await(()->find(v->"Folder windows, 2 windows".equals(v.getContentDescription()))!=null,"Explorer family grouped");tap(find(v->"Folder windows, 2 windows".equals(v.getContentDescription())),60);awaitNode("Switch to Destination");menuTap("Switch to Destination");check(second.active(),"Group switches to actual selected folder window");
        ui(()->home.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE));await(()->root.getWidth()>root.getHeight(),"Landscape ready");ui(()->{ViewGroup area=(ViewGroup)second.getParent();int width=area.getWidth()/2,height=area.getHeight();DesktopWindow first=window("@files");first.setX(0);first.setY(0);ViewGroup.LayoutParams one=first.getLayoutParams();one.width=width;one.height=height;first.setLayoutParams(one);second.setX(width);second.setY(0);ViewGroup.LayoutParams two=second.getLayoutParams();two.width=width;two.height=height;second.setLayoutParams(two);});Thread.sleep(300);await(()->find(explorer,v->"Drag Source.txt".equals(v.getContentDescription()))!=null,"Source icon supports drag");drag(find(explorer,v->"Drag Source.txt".equals(v.getContentDescription())),find(target,v->"Folder contents".equals(v.getContentDescription())));menuTap("Copy here");File copied=new File(destination,"Source.txt");await(copied::isFile,"Actual drag creates copy");check(source.isFile()&&Arrays.equals(bytes,java.nio.file.Files.readAllBytes(copied.toPath())),"Copy keeps source and exact bytes");shot("vista-folder-windows.png");
        File moveSource=new File(folder,"Move.txt");try(FileOutputStream out=new FileOutputStream(moveSource)){out.write(bytes);}ui(explorer::refreshFiles);await(()->find(explorer,v->"Drag Move.txt".equals(v.getContentDescription()))!=null,"Move source visible");drag(find(explorer,v->"Drag Move.txt".equals(v.getContentDescription())),find(target,v->"Folder contents".equals(v.getContentDescription())));menuTap("Move here");File moved=new File(destination,"Move.txt");await(()->moved.isFile()&&!moveSource.exists(),"Verified drag move completes");check(Arrays.equals(bytes,java.nio.file.Files.readAllBytes(moved.toPath())),"Move preserves exact bytes");
        ui(()->{home.open("@files");explorer.navigate(sourcePage);});await(()->find(explorer,v->"Destination".equals(v.getContentDescription()))!=null,"Source folder refreshed");tap(find(explorer,v->"Destination".equals(v.getContentDescription())),700);menuTap("Add desktop shortcut");await(()->FolderLinks.list(store).length()>0,"Real folder shortcut saved");check(destination.isDirectory(),"Adding shortcut leaves source intact");DesktopBackup.Plan backup=DesktopBackup.parse(DesktopBackup.snapshot(store).toString());check(backup.string("folder_links","{}").contains("Destination")&&backup.string("taskbar_grouping","").equals("Always"),"Validated backup retains folder links and grouping");
    }
    private void drag(View source,View destination)throws Exception{check(source!=null&&destination!=null,"Drag source and destination exist");Rect from=new Rect(),to=new Rect();check(source.getGlobalVisibleRect(from)&&destination.getGlobalVisibleRect(to),"Both drag windows have visible targets");long down=SystemClock.uptimeMillis();input(down,MotionEvent.ACTION_DOWN,from.exactCenterX(),from.exactCenterY());Thread.sleep(750);for(int i=1;i<=20;i++){input(down,MotionEvent.ACTION_MOVE,from.exactCenterX()+(to.exactCenterX()-from.exactCenterX())*i/20,from.exactCenterY()+(to.exactCenterY()-from.exactCenterY())*i/20);Thread.sleep(30);}input(down,MotionEvent.ACTION_UP,to.exactCenterX(),to.exactCenterY());Thread.sleep(250);}
    private void delete(File path){if(path.isDirectory()){File[] children=path.listFiles();if(children!=null)for(File child:children)delete(child);}path.delete();}
    private DesktopWindow window(String id){return (DesktopWindow)findAll(root,v->v instanceof DesktopWindow&&id.equals(((DesktopWindow)v).toolId));}
    private void close(String id)throws Exception{DesktopWindow w=window(id);if(w!=null){if(!w.isShown())ui(()->home.open(id));tap(find(w,v->"Close window".equals(v.getContentDescription())),60);}}
    private View text(View base,String text){return find(base,v->v instanceof TextView&&text.contentEquals(((TextView)v).getText()));}
    private View find(Predicate<View> match){return find(root,match);}private View find(View v,Predicate<View> match){if(v==null||!v.isShown())return null;if(match.test(v))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View result=find(((ViewGroup)v).getChildAt(i),match);if(result!=null)return result;}return null;}
    private View findAll(View v,Predicate<View> match){if(v==null)return null;if(match.test(v))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View result=findAll(((ViewGroup)v).getChildAt(i),match);if(result!=null)return result;}return null;}
    private void tap(View v,long hold)throws Exception{check(v!=null,"Native touch target exists");await(()->home.hasWindowFocus(),"Focused native target");ui(()->v.requestRectangleOnScreen(new Rect(0,0,v.getWidth(),v.getHeight()),true));getUiAutomation().waitForIdle(150,2500);Rect r=new Rect();check(v.isEnabled()&&v.getGlobalVisibleRect(r)&&!r.isEmpty(),"Native target has visible bounds: "+v.getContentDescription());long t=SystemClock.uptimeMillis();input(t,MotionEvent.ACTION_DOWN,r.exactCenterX(),r.exactCenterY());Thread.sleep(hold);input(t,MotionEvent.ACTION_UP,r.exactCenterX(),r.exactCenterY());Thread.sleep(100);}
    private void doubleTap(View v)throws Exception{Rect r=new Rect();check(v.getGlobalVisibleRect(r),"Caption has visible bounds");for(int i=0;i<2;i++){long t=SystemClock.uptimeMillis();input(t,MotionEvent.ACTION_DOWN,r.exactCenterX(),r.exactCenterY());Thread.sleep(35);input(t,MotionEvent.ACTION_UP,r.exactCenterX(),r.exactCenterY());Thread.sleep(60);}}
    private void input(long down,int action,float x,float y){MotionEvent e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,x,y,0);e.setSource(InputDevice.SOURCE_TOUCHSCREEN);check(getUiAutomation().injectInputEvent(e,true),"Native input injected");e.recycle();}
    private void menuTap(String text)throws Exception{awaitNode(text);getUiAutomation().waitForIdle(150,2500);AccessibilityNodeInfo node=node(text);check(node!=null&&node.isEnabled(),"Enabled menu command: "+text);Rect r=new Rect();node.getBoundsInScreen(r);long t=SystemClock.uptimeMillis();input(t,MotionEvent.ACTION_DOWN,r.exactCenterX(),r.exactCenterY());Thread.sleep(55);input(t,MotionEvent.ACTION_UP,r.exactCenterX(),r.exactCenterY());Thread.sleep(150);}
    private void awaitNode(String text)throws Exception{long end=SystemClock.uptimeMillis()+8000;while(SystemClock.uptimeMillis()<end){if(node(text)!=null)return;Thread.sleep(100);}throw new AssertionError("Native menu node: "+text);}
    private AccessibilityNodeInfo node(String text){return node(getUiAutomation().getRootInActiveWindow(),text);}private AccessibilityNodeInfo node(AccessibilityNodeInfo n,String text){if(n==null)return null;if(text.contentEquals(n.getText()==null?"":n.getText())||text.contentEquals(n.getContentDescription()==null?"":n.getContentDescription()))return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo r=node(n.getChild(i),text);if(r!=null)return r;}return null;}
    private void ui(Runnable r){runOnMainSync(r);try{Thread.sleep(80);}catch(InterruptedException e){throw new AssertionError(e);}}
    private void await(BooleanSupplier condition,String text)throws Exception{long end=SystemClock.uptimeMillis()+12000;while(SystemClock.uptimeMillis()<end){boolean[] ready={false};runOnMainSync(()->ready[0]=condition.getAsBoolean());if(ready[0])return;Thread.sleep(100);}throw new AssertionError(text);}
    private String shell(String command)throws Exception{try(ParcelFileDescriptor fd=getUiAutomation().executeShellCommand(command);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(fd);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);return out.toString("UTF-8");}}
    private void shot(String name)throws Exception{getUiAutomation().waitForIdle(150,2500);Bitmap image=getUiAutomation().takeScreenshot();check(image!=null,"Screenshot available");try(FileOutputStream out=getTargetContext().openFileOutput(name,0)){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
    private void dump(AccessibilityNodeInfo n,StringBuilder out,int depth){if(n==null||depth>24)return;out.append(depth).append(' ').append(n.getText()).append(" / ").append(n.getContentDescription()).append('\n');for(int i=0;i<n.getChildCount();i++)dump(n.getChild(i),out,depth+1);}
    private void progress(String text){Bundle result=new Bundle();result.putString("stream","CHECK: "+text+"\n");sendStatus(1,result);}private static void check(boolean value,String text){if(!value)throw new AssertionError(text);}
}
